excels.excel:

EXPORT WITH SHEET="员工绩效考核评分表", HEADER=true,
    MAPPING={"a":"工号","b":"姓名","c":"部门","d":"业绩分","e":"能力分","f":"态度分","g":"综合得分","h":"绩效等级"},
    FORMAT={"d":"0.0","e":"0.0","f":"0.0","g":"#,##0.00"},
    FORMULAS={
        G2:'D2*0.5+E2*0.3+F2*0.2',
        G3:'D3*0.5+E3*0.3+F3*0.2',
        G4:'D4*0.5+E4*0.3+F4*0.2',
        G5:'D5*0.5+E5*0.3+F5*0.2',
        G6:'D6*0.5+E6*0.3+F6*0.2',
        D7:'AVERAGE(D2:D6)',E7:'AVERAGE(E2:E6)',F7:'AVERAGE(F2:F6)',G7:'AVERAGE(G2:G6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        H6:{color:red,bold:true}
    }
